package com.mengzhihua.crm.service.service;
import com.mengzhihua.crm.common.*; import com.mengzhihua.crm.service.entity.*; import com.mengzhihua.crm.service.repository.*;
import org.springframework.stereotype.Service;
@Service public class KnowledgeService {private final KnowledgeRepository repo;public KnowledgeService(KnowledgeRepository r){repo=r;}public PageResult<KnowledgeArticle> list(int page,int size,String k){return DtoUtil.page(k==null||k.isEmpty()?repo.findAll(DtoUtil.pageable(page,size)):repo.findByTitleContainingIgnoreCaseOrKeywordsContainingIgnoreCaseOrContentContainingIgnoreCase(k,k,k,DtoUtil.pageable(page,size)),x->(KnowledgeArticle)x);}public KnowledgeArticle get(Long id){KnowledgeArticle x=repo.findById(id).orElseThrow(()->new BizException("文章不存在"));x.setViewCount((x.getViewCount()==null?0:x.getViewCount())+1);return repo.save(x);}public KnowledgeArticle save(KnowledgeArticle x){if(x.getStatus()==null)x.setStatus(Enums.ArticleStatus.DRAFT);if(x.getViewCount()==null)x.setViewCount(0L);return repo.save(x);}public void delete(Long id){repo.deleteById(id);}public KnowledgeArticle publish(Long id){KnowledgeArticle x=repo.findById(id).orElseThrow(()->new BizException("文章不存在"));x.setStatus(Enums.ArticleStatus.PUBLISHED);return repo.save(x);}}
